		.timestamp = time(NULL),
		.has_optional_field = 1,
		.optional_field = 9001
	};

	// serialise
	stream.serialise(packet_in);

	// round-trip deserialise
	UserPacket packet_out{};
	stream.deserialise(packet_out);

	if(packet_in == packet_out) {
