struct BufferInfo {
    size_t readable_size;
    size_t free_space;
};

BufferInfo check_buffer_space(const std::vector<uint8_t>& buffer) {
    // Check available buffer space
    // readable_size: corresponds to buffer_adaptor::size() - data available to read
    // free_space: corresponds to buffer_adaptor::free() - space available for writing
    BufferInfo info;
    info.readable_size = buffer.size();  // Amount of data currently in the buffer
    info.free_space = buffer.capacity() - buffer.size();  // Available space before reallocation
    return info;
}
