bool write_data_with_check(std::vector<uint8_t>& buffer, uint32_t header, const std::vector<uint32_t>& items) {
    // Calculate required space: header + count prefix + items data
    const size_t required_space = sizeof(uint32_t) + sizeof(uint32_t) + items.size() * sizeof(uint32_t);

    // Check available space
    if (buffer.size() < required_space) {
        return false;
    }

    // Create buffer_adaptor with init_empty
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(buffer, hexi::init_empty);

    // Get the write pointer
    auto write_ptr = adaptor.write_ptr();

    // Create binary_stream from the adaptor
    hexi::binary_stream stream(adaptor);

    // Write header
    stream << header;

    // Write container data (prefixed uses write_container internally)
    stream << hexi::prefixed(items);

    return true;
