	using unique_storage = std::unique_ptr<storage_type, std::function<void(storage_type*)>>;

private:
	intrusive_node root_;
	size_type size_;
	[[no_unique_address]] allocator allocator_;

	void link_tail_node(intrusive_node* node) {
		node->next = &root_;
		node->prev = root_.prev;
