	size_type find_first_of(value_type value) const override {
		size_type index = 0;
		auto head = root_.next;

		while(head != &root_) {
			const auto buffer = buffer_from_node(head);
			const auto data = buffer->read_data();

			for(const auto& byte : data) {
				if(byte == value) {
					return index;
				}

				++index;
			}

			head = head->next;
		}

		return npos;
	}

