#pragma once

#include <utility>

namespace hexi {

template<typename T>
struct default_allocator final {
	template<typename ...Args>
	[[nodiscard]] inline T* allocate(Args&&... args) const {
		return new T(std::forward<Args>(args)...);
	}

	inline void deallocate(T* t) const {
		delete t;
	}
};

