#endif
			block = new mem_block;
			block->meta.using_new = true;
		}

		if constexpr(std::is_same_v<ValidatePolicy, validate_dealloc>) {
			block->meta.thread_id = thread_id_;
		}

#ifdef HEXI_DEBUG_ALLOCATORS
		++total_allocs;
		++active_count;
#endif
