};

template<typename T, typename U>
concept has_serialise =
	requires(T t, stream_write_adaptor<U>& u) {
		{ t.serialise(u) } -> std::same_as<void>;
};

template<typename T, typename U>
concept has_deserialise =
	requires(T t, stream_read_adaptor<U>& u) {
