		if(!file_) {
			error_ = true;
			return;
		}

		if(std::fseek(file_, 0, SEEK_END)) {
			error_ = true;
			return;
		}

		write_ = std::ftell(file_);

		if(write_ == -1) {
			error_ = true;
		}
	}

	file_buffer(file_buffer&& rhs) noexcept
		: file_(rhs.file_),
		  read_(rhs.read_),
		  write_(rhs.write_),
		  error_(rhs.error_) {
		rhs.file_ = nullptr;
	}

	file_buffer& operator=(file_buffer&& rhs) noexcept {
		std::exchange(file_, rhs.file_);
		read_ = rhs.read_;
		write_ = rhs.write_;
		error_ = rhs.error_;
		return *this;
	}

	file_buffer& operator=(const file_buffer&) = delete;
	file_buffer(const file_buffer&) = delete;

	~file_buffer() {
		close();
	}


	/**
	 * @brief Flush unwritten data.
	 */
	void flush() {
		std::fflush(file_);
	}

	/**
	 * @brief Reads a number of bytes to the provided buffer.
	 * 
