struct Foo {
	std::uint16_t x;
	std::uint32_t y;
	std::uint64_t z;
	std::string_view str;

	void serialise(auto& stream) {
		stream(x, y, z, hexi::null_terminated(str));
		stream & hexi::endian::be(x);
	}

	bool operator==(const Foo& rhs) const {
		return x == rhs.x && y == rhs.y && z == rhs.z && str == rhs.str;
	}
};

