TEST(binary_stream_pmc, string_adaptor_prefixed_varint_long) {
	std::vector<char> buffer;
	hexi::pmc::buffer_adaptor adaptor(buffer);
	hexi::pmc::binary_stream stream(adaptor);

	std::string input;

	// encode varint requiring three bytes
