#include <hexi/hexi.h>
#include <vector>
#include <string>
#include <cstdint>
#include <span>

struct CompactPacket {
    uint32_t packet_id;
    std::vector<std::string> tags;
    std::string data;
};

std::vector<uint8_t> serialize_compact_packet(const CompactPacket& packet) {
    // Create buffer and stream for serialization
    std::vector<uint8_t> buffer;
    hexi::buffer_adaptor adaptor(buffer, hexi::init_empty);
    hexi::binary_stream stream(adaptor);

    // Serialize packet_id as regular uint32_t
    stream << packet.packet_id;

    // Serialize tags vector using prefixed_varint adaptor
    // This writes a varint-encoded size followed by the vector elements
    stream << hexi::prefixed_varint(packet.tags);

    // Serialize data string using prefixed_varint adaptor
    // This writes a varint-encoded length followed by the string content
    stream << hexi::prefixed_varint(packet.data);

    return buffer;
}

CompactPacket deserialize_compact_packet(const std::span<const uint8_t> buffer) {
    CompactPacket packet;

    // Create a mutable copy of the buffer for the adaptor
    std::vector<uint8_t> mutable_buffer(buffer.begin(), buffer.end());
    hexi::buffer_adaptor adaptor(mutable_buffer);
    hexi::binary_stream stream(adaptor);

    // Deserialize packet_id
    stream >> packet.packet_id;

    // Deserialize tags vector using prefixed_varint adaptor
    // This reads a varint-encoded size and then reads that many elements
    stream >> hexi::prefixed_varint(packet.tags);

    // Deserialize data string using prefixed_varint adaptor
    // This reads a varint-encoded length and then reads that many bytes
    stream >> hexi::prefixed_varint(packet.data);

    return packet;
}
```

**Key Points:**

1. **Varint Encoding**: The `prefixed_varint` adaptor uses variable-length integer encoding where:
   - Small values (0-127) use 1 byte
   - Larger values use additional bytes as needed
   - Each byte stores 7 bits of data and 1 continuation bit

2. **Serialization Flow**:
   - `packet_id`: Serialized as regular 4-byte uint32_t
   - `tags`: Varint-encoded count + individual strings (each with varint-encoded length)
   - `data`: Varint-encoded length + raw string bytes

3. **Buffer Management**: 
   - Uses `hexi::buffer_adaptor` to wrap `std::vector<uint8_t>`
   - `init_empty` ensures the buffer starts empty during serialization
   - Deserialization requires a mutable buffer copy

4. **Compact Encoding Benefits**:
   - Small packet IDs and short strings use fewer bytes
   - More efficient than fixed-size prefixes for typical data

