struct except_tag {};
struct allow_throw_t : except_tag {};
struct no_throw_t : except_tag {};

[[maybe_unused]] constexpr static no_throw_t no_throw {};
[[maybe_unused]] constexpr static allow_throw_t allow_throw {};

