#define STREAM_READ_BOUNDS_ENFORCE(read_size, ret_var)            \
	if(state_ != stream_state::ok) [[unlikely]] {                 \
		return ret_var;                                           \
	}                                                             \
                                                                  \
	enforce_read_bounds(read_size);                               \
	                                                              \
